class basic_ofstream : public basic_ostream {
private:
    basic_filebuf buf;

public:
    // Implementation of Move Constructor
    basic_ofstream(basic_ofstream&& other) noexcept
        : basic_ostream(std::move(other)),  // Move base (stream state)
          buf(std::move(other.buf))         // Move resource (file handle/buffer)
    {
        // Re-link the base stream pointer to *this* newly moved buffer
        // (basic_ostream::set_rdbuf)
        this->set_rdbuf(&buf);

        // Invalidate original stream's link
        other.set_rdbuf(nullptr);
    }
};
